#include "dfre/mission_object_helo_home.hpp"
#include <array>
#include <iostream>
#include <sstream>
using namespace dfre;using U=std::uint32_t;
int main(){try{std::string line;while(std::getline(std::cin,line)){
 U body,distance,sine,cosine,mode,mutation,fail;std::string hex;std::istringstream in(line);if(!(in>>body>>distance>>sine>>cosine>>mode>>mutation>>fail>>hex)||hex.size()!=0x228)throw MissionTickError("Short helicopter home fixture");constexpr U A=0x7dde80,P=0x794680,F=0x1300000;AiActorImage actor{};std::array<std::uint8_t,0xb4> person{};std::array<std::uint8_t,0x40> frame{};frame.fill(0xa5);for(U i=0;i<0x114;++i)actor[i]=std::uint8_t(std::stoul(hex.substr(i*2,2),nullptr,16));
 auto byte=[&](U at)->std::uint8_t&{if(at>=A&&at<A+actor.size())return actor.at(at-A);if(at>=P&&at<P+person.size())return person.at(at-P);if(at>=F&&at<F+frame.size())return frame.at(at-F);throw MissionTickError("Helicopter home fixture address");};auto put=[&](U at,U n,U width=4){for(U i=0;i<width;++i)byte(at+i)=std::uint8_t(n>>(i*8));};auto get=[&](U at,U width=4){U n=0;for(U i=0;i<width;++i)n|=U(byte(at+i))<<(i*8);return n;};put(A+0xc,P);put(P+0x54,get(A+0xe0));put(P+0x58,get(A+0xe4));put(P+0x2c,get(A+0xe8));put(F+0x30,A);put(F+0x34,get(A+0xec));put(F+0x38,get(A+0xf0));put(F+0x3c,mode);
 U calls=0,grounds=0,trigs=0;std::ostringstream trace;MissionObjectHeloBindings b;b.read=[&](U at,U width){const U n=get(at,width);trace<<'R'<<at<<','<<width<<','<<n<<';';return n;};b.write=[&](U at,U width,U n){put(at,n,width);trace<<'W'<<at<<','<<width<<','<<n<<';';if(at==A+0xb0){if((mutation&8)&&n==0)put(A+0xd4,12);if(mutation&16)put(A+0xb0,0x12345678);}};
 b.call=[&](U site,const std::vector<U>& args)->U{trace<<'C'<<site;for(U n:args)trace<<','<<n;trace<<';';if(++calls==fail)throw MissionTickError("Fixture call stopped");if(site==0x477770){if(mutation&1){put(A+0x24,11);put(A+0x28,22);put(P+0x54,33);}return 0x11223344;}if(site==0x477670)return distance;if(site==0x477820){put(args.at(1),sine);put(args.at(2),cosine);++trigs;if(mutation&4){if(trigs==1)put(P+0x2c,63);else put(A+0x7c,get(A+0x7c)^0x80000000u);}return 0;}if(site==0x47df40){++grounds;if(mutation&2){put(A+0x24,get(A+0x24)+0x10000);put(A+0x28,get(A+0x28)-0x20000);}return (mutation&64)?0u:(args.at(0)^args.at(1)^grounds*0x12345678u);}if(site==0x486fd0){if(mutation&32){put(F+0x38,0x20000);put(F+0x3c,31);}return 0x12345;}if(site==0x450100){put(A+0x2c,0x44556677);return 0;}throw MissionTickError("Unknown helicopter fixture call");};
 bool failed=false;U result=0;try{if(body)mission_object_helo_altitude(b,F);else result=mission_object_helo_home(b,A);}catch(const MissionTickError&){failed=true;}std::uint64_t hash=1469598103934665603ull;auto add=[&](const auto& bytes){for(auto n:bytes){hash^=n;hash*=1099511628211ull;}};add(actor);add(person);if(body){for(U i=0;i<0x1c;++i){hash^=frame[i];hash*=1099511628211ull;}for(U i=0x30;i<0x40;++i){hash^=frame[i];hash*=1099511628211ull;}}std::cout<<failed<<' '<<result<<' '<<hash<<' '<<trace.str()<<'\n';
}return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
